import pytest

import factory


@pytest.mark.parametrize('choice', [False, True])
@pytest.mark.parametrize('locale', [None, 'en_US', 'fr_FR'])
def test_faker_decider_defaults(choice, locale):
    class ExampleFactory(factory.DictFactory):
        value = factory.Maybe(
            factory.Faker('pybool', truth_probability=100 if choice else 0, locale=locale),
            yes_declaration='yes',
            no_declaration='no',
        )

    assert ExampleFactory.create_batch(3) == [{'value': 'yes' if choice else 'no'}] * 3


def test_faker_decider_unrolls_arguments_and_keeps_branch_overrides():
    class ExampleFactory(factory.DictFactory):
        probability = 100
        value = factory.Maybe(
            factory.Faker('pybool', truth_probability=factory.SelfAttribute('..probability')),
            yes_declaration=factory.Faker('pystr', min_chars=3, max_chars=3),
            no_declaration='no',
        )

    assert len(ExampleFactory(value__min_chars=8, value__max_chars=8)['value']) == 8
    assert ExampleFactory(probability=0)['value'] == 'no'


def test_decider_with_custom_pre_evaluation():
    class ExampleFactory(factory.DictFactory):
        value = factory.Maybe(
            factory.Transformer(False, transform=lambda value: not value),
            yes_declaration='yes',
            no_declaration='no',
        )

    assert ExampleFactory()['value'] == 'yes'
