import pytest

import factory


@pytest.mark.parametrize('locale', [None, 'en_US', 'fr_FR'])
@pytest.mark.parametrize('chance, expected', [(0, 'no'), (100, 'yes')])
def test_faker_decider_defaults(locale, chance, expected):
    class TestFactory(factory.DictFactory):
        value = factory.Maybe(
            factory.Faker('boolean', locale=locale, chance_of_getting_true=chance),
            yes_declaration='yes',
            no_declaration='no',
        )

