def test_faker_decider_unrolls_defaults(chance, expected):
    class TestFactory(factory.DictFactory):
        value = factory.Maybe(
            factory.Faker(
                'boolean',
                chance_of_getting_true=factory.LazyFunction(lambda: chance),
            ),
            yes_declaration='yes',
            no_declaration='no',
        )

    assert TestFactory()['value'] == expected


def test_nested_maybe_decider_and_branch_overrides():
