        value = factory.Maybe(
            factory.Maybe(factory.LazyFunction(lambda: True), True, False),
            yes_declaration=factory.Faker('pyint', min_value=1, max_value=1),
            no_declaration=0,
        )

    assert TestFactory(value__min_value=7, value__max_value=7)['value'] == 7
